mapper.select:
SELECT ava.cdate, ava.PORTFOLIO_ID portfolioId, fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ID finProdId, nvl(fp.FINPROD_ABBR, fp.FINPROD_NAME) bondName, B.TRADE_PLACE tradePlace, ava.SEC_ACCT_ID secAcctId, ava.CCY ccy,
NVL(ava.AMOUNT, 0)*100 positionTotal,
NVL(inTotalPrinAmt.AMOUNT, 0)*100 inTotalPrinAmt,
fscr.SCALE*100 discountRate,
NVL(inTotalPrinAmt.AMOUNT, 0)*100*NVL(fscr.SCALE, 0) stdrdPrinAmt,
NVL(standardPledge.AMOUNT, 0) pledgePrinAmt,
'' pledgeStdrdPrinAmt,
'' avaStrdPrinAmt FROM ( SELECT PORTFOLIO_ID, FINPROD_ID, SEC_ACCT_ID, CCY, TO_CHAR(CDATE, 'yyyy-MM-dd') CDATE, SUM(NVL(AMOUNT, 0)) AMOUNT FROM PTL_SEC_POSITION WHERE HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_03})
AND PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}
AND CDATE = TO_DATE(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd')
AND SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
GROUP BY PORTFOLIO_ID, FINPROD_ID, SEC_ACCT_ID, CCY, CDATE ) ava LEFT JOIN ( SELECT tpda.PORTFOLIO_ID, tpd.SEC_MANAGE_ACCT_ID SEC_ACCT_ID, tpd.CCY, SUM(DECODE(TPD.PS, 'T23', NVL(TPD.PRIN_AMT, 0) * -1, NVL(TPD.PRIN_AMT, 0))) AMOUNT
FROM TRD_PRODUCT_DEAL tpd LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpda.TRADE_ID = tpd.TRADE_ID WHERE fpt.TYPE_6 = #{TARGET_BACK_TYPE_H02} AND tpd.TRADE_STATUS = #{TRADE_STATUS_01} AND tpd.IS_CANCEL = 'N' AND TPD.PS IN ('T23', 'T01')
AND tpda.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}
AND tpd.SEC_MANAGE_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND TPD.Trade_Date <= TO_DATE(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd')
AND tpd.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F02}
GROUP BY tpda.PORTFOLIO_ID, tpd.SEC_MANAGE_ACCT_ID, tpd.CCY ) standardPledge ON standardPledge.SEC_ACCT_ID = ava.SEC_ACCT_ID AND standardPledge.PORTFOLIO_ID = ava.PORTFOLIO_ID AND standardPledge.CCY = ava.CCY LEFT JOIN () inTotalPrinAmt ON inTotalPrinAmt.PORTFOLIO_ID = ava.PORTFOLIO_ID AND inTotalPrinAmt.SEC_ACCT_ID = ava.SEC_ACCT_ID AND inTotalPrinAmt.FINPROD_ID = ava.FINPROD_ID INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = ava.FINPROD_ID
AND fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
INNER JOIN PTL_SEC_ACCT psa ON psa.PORTFOLIO_ID = ava.PORTFOLIO_ID AND psa.ACCT_NO = ava.SEC_ACCT_ID INNER JOIN STL_SEC_ACCT_INFO B ON B.SEC_ACCT_ID = psa.ACCT_NO LEFT JOIN FIN_STDSEC_CONVERSE_RADIO fscr ON fscr.FINPROD_ID = ava.FINPROD_ID AND fscr.BRANCH = #{BRANCH_0, jdbcType=VARCHAR} AND fscr.VDATE <= TO_DATE(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT * FROM FIN_STDSEC_CONVERSE_RADIO fscrInner WHERE fscrInner.FINPROD_ID = fscr.FINPROD_ID AND fscrInner.BRANCH = #{BRANCH_0, jdbcType=VARCHAR} AND fscrInner.VDATE <= TO_DATE(#{searchDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND fscrInner.VDATE > fscr.VDATE )
NVL(AVA.AMOUNT, 0) > 0
AND ava.FINPROD_ID in
#{item}
and B.TRADE_PLACE = #{tradePlace}
and B.TRADE_PLACE in (#{TRADEPLACE03},#{TRADEPLACE04})

SELECT A.FINPROD_ID id, A.FINPROD_MARKET_ID text, A.FINPROD_NAME, TO_CHAR(A.VDATE, 'yyyy-MM-dd') VDATE, TO_CHAR(A.MDATE, 'yyyy-MM-dd') MDATE, TO_CHAR(A.IDATE, 'yyyy-MM-dd') IDATE, A.TRADE_MARKET, A.CCY, A.CALENDAR_ID, basisData.BASIS, B.TYPE_4 windtypeone, A.FINPROD_MARKET_ID, A.IS_RIGHT, A.REGIST_ORG FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID LEFT JOIN ( SELECT max(BASIS) as BASIS, FINPROD_ID FROM FIN_CASH_CALC_RULE
AND FINPROD_ID = #{initValue}
GROUP BY FINPROD_ID ) basisData ON A.FINPROD_ID = basisData.FINPROD_ID
( A.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.FINPROD_ID = #{initValue}
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}

SELECT DISTINCT A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
and B.TRADE_PLACE in (#{TRADEPLACE03},#{TRADEPLACE04})
AND A.PORTFOLIO_ID = #{portfolioId}
and B.TRADE_PLACE = #{tradePlace}
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{param}, '%'))` `1 OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{param}, '%')) )
AND A.ACCT_NO = #{initValue}
